function audit(action,entity,id,detail,before=null,after=null){AuditEngine.record(state,currentUser,action,entity,id,detail,before,after);save()}
function today(){return new Date().toISOString().slice(0,10)} function uid(p){return p+'-'+Date.now()+'-'+Math.random().toString(36).slice(2,6)}
const UI_LANG_KEY='rpia-language-v1';
let uiLanguage=localStorage.getItem(UI_LANG_KEY)||'en';
const uiText={en:{welcome:'Welcome to RP IA',sub:'Develop skills. Build confidence. Strengthen the team.',sign:'Sign in',ready:'System ready',user:'Username',pass:'Password',privacy:'Private pilot. Data and local learning remain on this device.'},es:{welcome:'Bienvenido a RP IA',sub:'Desarrolla habilidades. Fortalece la confianza. Impulsa al equipo.',sign:'Iniciar sesión',ready:'Sistema listo',user:'Usuario',pass:'Contraseña',privacy:'Piloto privado. Los datos y el aprendizaje local permanecen en este dispositivo.'}};
function applyLanguage(lang,remember=true){uiLanguage=lang;if(remember)localStorage.setItem(UI_LANG_KEY,lang);document.documentElement.lang=lang;const t=uiText[lang];if($('#welcomeTitle'))$('#welcomeTitle').textContent=t.welcome;if($('#welcomeSub'))$('#welcomeSub').textContent=t.sub;if($('#loginBtn'))$('#loginBtn').textContent=t.sign;if($('#startupStatus'))$('#startupStatus').textContent=t.ready;if($('#privacyNote'))$('#privacyNote').textContent=t.privacy;if($('#username'))$('#username').placeholder=t.user;if($('#pin'))$('#pin').placeholder=t.pass;if($('#languageLabel'))$('#languageLabel').textContent=lang==='es'?'Español':'English';$('#langEn')?.classList.toggle('active',lang==='en');$('#langEs')?.classList.toggle('active',lang==='es');$('#languageMenu')?.classList.add('hidden');$('#languageMenuBtn')?.setAttribute('aria-expanded','false');if(currentUser){currentUser.language=lang;saveUsers();renderNav();navigate(view)}}
function canManageMetl(){return currentUser?.role==='admin'||(currentUser?.role==='evaluator'&&currentUser?.maxLevel==='-40'&&currentUser?.manageMetl===true)}
function canEvaluate(){return currentUser?.role==='admin'||currentUser?.role==='evaluator'}
function canManagePersonnel(){return currentUser?.role==='admin'||currentUser?.managePersonnel===true}
function myProfile(){const u=currentUser;page(uiLanguage==='es'?'Mi perfil':'My Profile',uiLanguage==='es'?'Preferencias personales y seguridad':'Personal preferences and security',`<div class="profile-grid"><div class="card"><h3>${uiLanguage==='es'?'Cuenta':'Account'}</h3><p><b>${esc(u.name)}</b></p><p>${esc(u.role)} ${u.maxLevel||''}</p><label>${uiLanguage==='es'?'Idioma':'Language'}<select id="profileLanguage"><option value="en" ${uiLanguage==='en'?'selected':''}>English</option><option value="es" ${uiLanguage==='es'?'selected':''}>Español</option></select></label></div><div class="card"><h3>${uiLanguage==='es'?'Cambiar contraseña':'Change password'}</h3><label>${uiLanguage==='es'?'Contraseña actual':'Current password'}<input id="oldPwd" type="password"></label><label>${uiLanguage==='es'?'Nueva contraseña':'New password'}<input id="profileNewPwd" type="password" minlength="6"></label><label>${uiLanguage==='es'?'Confirmar contraseña':'Confirm password'}<input id="profileConfirmPwd" type="password" minlength="6"></label><button class="primary" id="saveProfilePwd">${uiLanguage==='es'?'Guardar contraseña':'Save password'}</button></div><div class="card full"><h3>Eagle AI</h3><p>${uiLanguage==='es'?'El cerebro local personaliza el orden de tus recomendaciones según tu actividad reciente. No modifica evaluaciones ni permisos.':'The local brain personalizes recommendation order from your recent activity. It never changes assessments or permissions.'}</p><button class="secondary" id="resetBrain">${uiLanguage==='es'?'Reiniciar aprendizaje personal':'Reset my learning'}</button></div></div>`);$('#profileLanguage').onchange=e=>applyLanguage(e.target.value);$('#saveProfilePwd').onclick=()=>{const a=$('#oldPwd').value,b=$('#profileNewPwd').value,c=$('#profileConfirmPwd').value;if(a!==u.password)return toast(uiLanguage==='es'?'Contraseña actual incorrecta':'Current password is incorrect');if(b.length<6)return toast(uiLanguage==='es'?'Use al menos 6 caracteres':'Use at least 6 characters');if(b!==c)return toast(uiLanguage==='es'?'Las contraseñas no coinciden':'Passwords do not match');u.password=b;saveUsers();toast(uiLanguage==='es'?'Contraseña actualizada':'Password updated')};$('#resetBrain').onclick=()=>{localStorage.removeItem('rpia-brain-'+u.username);toast(uiLanguage==='es'?'Aprendizaje reiniciado':'Learning reset')}}
function trackInterest(topic,weight=1){if(!currentUser)return;const key='rpia-brain-'+currentUser.username;let d={};try{d=JSON.parse(localStorage.getItem(key))||{}}catch{};for(const k in d)d[k]*=.985;d[topic]=(d[topic]||0)+weight;localStorage.setItem(key,JSON.stringify(d))}
function brainTop(){if(!currentUser)return[];try{return Object.entries(JSON.parse(localStorage.getItem('rpia-brain-'+currentUser.username))||{}).sort((a,b)=>b[1]-a[1]).slice(0,4)}catch{return[]}}
function login(){const name=$('#username').value.trim().toLowerCase(),pwd=$('#pin').value;const u=authUsers.find(x=>x.username.toLowerCase()===name);if(!u||u.password!==pwd)return toast('Invalid username or password');if(u.disabled)return toast('This account is not active. Contact an administrator.');pendingUser=u;if(u.mustChange){$('#changePasswordUser').textContent=u.username;$('#passwordModal').classList.remove('hidden');return}completeLogin(u)}
function changePassword(){const a=$('#newPassword').value,b=$('#confirmPassword').value;if(a.length<6)return toast('Use at least 6 characters');if(a!==b)return toast('Passwords do not match');if(a===pendingUser.password)return toast('Choose a different password');pendingUser.password=a;pendingUser.mustChange=false;saveUsers();$('#passwordModal').classList.add('hidden');completeLogin(pendingUser)}
function completeLogin(u){currentUser=u;uiLanguage=u.language||uiLanguage;applyLanguage(uiLanguage,false);$('#login').classList.add('hidden');$('#app').classList.remove('hidden');$('#serverConfigBtn')?.classList.toggle('hidden',u.role!=='admin');$('#roleBadge').textContent=u.role==='admin'?' · Administrator':u.role==='viewer'?' · Read only':` · Approved Evaluator ${u.maxLevel}`;renderNav();navigate('dashboard')}
function logout(){currentUser=null;$('#serverConfigBtn')?.classList.add('hidden');$('#app').classList.add('hidden');$('#login').classList.remove('hidden');$('#pin').value='';$('#username').focus()}
const navDefs=[['dashboard','Dashboard','Inicio'],['intelligence','Eagle AI','Eagle AI'],['personnel','Personnel','Personal'],['tasks','METL & Subtasks','METL y subtareas'],['matrix','Readiness Matrix','Matriz de preparación'],['assess','Assessment','Evaluación'],['sessions','Assessment History','Historial de evaluaciones'],['actions','Corrective Actions','Acciones correctivas'],['notifications','Notifications','Notificaciones'],['audit','Audit Trail','Auditoría'],['plant','Plant Intelligence','Inteligencia de planta'],['knowledge','Knowledge Center','Centro de conocimiento'],['engines','Engine Center','Centro de motores'],['profile','My Profile','Mi perfil'],['settings','Administration','Administración']];
function renderNav(){const allowed=navDefs.filter(x=>{if(x[0]==='settings')return currentUser.role==='admin';if(x[0]==='assess')return canEvaluate();if(x[0]==='audit')return currentUser.role==='admin'||currentUser.role==='evaluator';return true});$('#nav').innerHTML=allowed.map(([id,en,es])=>`<button data-view="${id}">${uiLanguage==='es'?es:en}</button>`).join('')+`<div class="nav-spacer"></div><div class="nav-footer"><strong>RP IA</strong>${uiLanguage==='es'?'Impulsado por RP IA':'Powered by RP IA'}</div>`;$$('#nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.view))}
function navigate(v){
  view=v;
  trackInterest(v,1);
  $$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));
  $('#nav').classList.remove('open');
  $('#navScrim').classList.remove('open');
  const routes={
    dashboard,
    intelligence:metlIntelligence,
    personnel,
    tasks,
    matrix:matrixView,
    assess,
    sessions:sessionHistory,
    actions,
    notifications:notificationView,
    audit:auditView,
    plant:plantIntelligenceView,
    knowledge:knowledgeCenterView,
    engines:engineCenterView,
    profile:myProfile,
    settings
  };
  try{
    (routes[v]||dashboard)();
  }catch(err){
    console.error('RP IA view error',v,err);
    page('Unable to open this view','The rest of RP IA is still available.',`<div class="card"><h3>View error</h3><p>${esc(err?.message||'Unknown error')}</p><button class="primary" id="returnDashboard">Return to dashboard</button></div>`);
    $('#returnDashboard').onclick=()=>navigate('dashboard');
  }
}
function page(title,sub,body,acts=''){$('#main').innerHTML=`<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${acts}</div></div>${body}`}
function activePeople(){return state.personnel.filter(p=>p.name&&p.employeeNumber&&p.status!=='Inactive')}
function latestResults(emp=null){const map=new Map();state.results.filter(r=>!emp||r.employeeNumber===emp).forEach(r=>{const key=r.employeeNumber+'|'+r.subtaskId,old=map.get(key);const d=r.date||state.sessions.find(s=>s.id===r.sessionId)?.date||'';if(!old||d>old._date)map.set(key,{...r,_date:d})});return map}
function personMetrics(p){const applicable=state.subtasks.filter(s=>s.status==='Active'&&levelRank[s.requiredLevel]<=levelRank[p.assignedLevel]);const latest=latestResults(p.employeeNumber);let go=0,nogo=0,assist=0,expired=0,critical=0;for(const s of applicable){const r=latest.get(p.employeeNumber+'|'+s.id);if(r?.result==='GO')go++;else if(r?.result==='NO-GO'){nogo++;if(s.criticality==='Critical Gate')critical++}else if(r?.result==='REQUIRES ASSISTANCE')assist++;else if(r?.result==='EXPIRED')expired++}const pct=applicable.length?Math.round(go/applicable.length*100):0;const open=state.actions.filter(a=>a.employeeNumber===p.employeeNumber&&a.status!=='Closed').length;let highest='None';for(const lv of ['-10','-20','-30','-40']){const req=state.subtasks.filter(s=>s.status==='Active'&&levelRank[s.requiredLevel]<=levelRank[lv]);const ok=req.length&&req.every(s=>latest.get(p.employeeNumber+'|'+s.id)?.result==='GO');if(ok)highest=lv}return{applicable:applicable.length,go,nogo,assist,expired,critical,open,pct,highest}}

function reconcileCriticalGateActions(){
  if(!Array.isArray(state.results)||!Array.isArray(state.actions))return 0;
  const latest=new Map();
  for(const r of state.results){
    if(String(r.criticality||'').trim()!=='Critical Gate')continue;
    const key=String(r.employeeNumber||'')+'|'+String(r.subtaskId||'');
    const session=state.sessions.find(x=>x.id===r.sessionId)||{};
    const stamp=String(r.createdAt||session.signedAt||r.date||session.date||'');
    const old=latest.get(key);
    if(!old||stamp>=old.stamp)latest.set(key,{record:r,session,stamp});
  }
  let created=0;
  for(const {record:r,session} of latest.values()){
    if(['GO','NOT EVALUATED'].includes(String(r.result||'')))continue;
    const sourceId=String(r.sessionId||session.id||'');
    const exists=state.actions.some(a=>
      (sourceId&&String(a.sourceAssessmentId||'')===sourceId&&String(a.subtaskId||'')===String(r.subtaskId||'')) ||
      (a.status!=='Closed'&&String(a.employeeNumber||'')===String(r.employeeNumber||'')&&String(a.taskId||'')===String(r.taskId||'')&&String(a.subtaskId||'')===String(r.subtaskId||''))
    );
    if(exists)continue;
    const person=state.personnel.find(x=>String(x.employeeNumber||'')===String(r.employeeNumber||''))||{};
    const due=session.reassessmentDate||new Date(Date.now()+(Number(state.settings?.defaultCorrectiveActionDays)||14)*86400000).toISOString().slice(0,10);
    const action={
      id:uid('CA'),employeeNumber:String(r.employeeNumber||''),employee:r.associateName||person.name||'Unknown associate',shift:r.shift||person.shift||'',
      taskId:r.taskId||session.taskId||'',subtaskId:r.subtaskId||'',requiredLevel:r.requiredLevel||'',
      standardNotMet:r.observation||r.standardSnapshot||r.subtaskName||'Critical Gate standard was not met',
      immediateCoaching:'',requiredRetraining:session.correctiveAction||'Critical Gate retraining and reassessment required',
      responsibleTrainer:session.evaluatorName||r.evaluatorName||'',targetDate:due,reassessmentDate:session.reassessmentDate||'',reassessmentResult:'',
      status:'Open',criticality:'Critical Gate',created:new Date().toISOString(),createdBy:'System recovery',sourceAssessmentId:sourceId,workflowStatus:'Retraining Required'
    };
    state.actions.push(action);
    if(window.WorkflowEngine?.create)WorkflowEngine.create(state,'Corrective Action & Reassessment',{actionId:action.id,assessmentId:sourceId,employeeNumber:action.employeeNumber,subtaskId:action.subtaskId},currentUser||{name:'System'});
    AuditEngine.record(state,currentUser||{name:'System'},'RECOVER','Corrective Action',action.id,'Created missing Critical Gate follow-up from assessment history',null,action);
    created++;
  }
  if(created)save();
  return created;
}
window.reconcileCriticalGateActions=reconcileCriticalGateActions;

function dashboard(){const interests=brainTop();const people=activePeople(),metrics=people.map(p=>({...p,...personMetrics(p)}));const total=metrics.length,ready=metrics.filter(x=>x.pct===100&&!x.open&&!x.critical).length,open=state.actions.filter(a=>a.status!=='Closed').length,crit=metrics.reduce((a,x)=>a+x.critical,0),overdue=state.actions.filter(a=>a.status!=='Closed'&&a.targetDate&&a.targetDate<today()).length;const shifts=['A','B','C','D'].map(sh=>{const r=metrics.filter(x=>x.shift===sh);return{shift:sh,count:r.length,pct:r.length?Math.round(r.reduce((a,x)=>a+x.pct,0)/r.length):0,critical:r.reduce((a,x)=>a+x.critical,0)}});page(uiLanguage==='es'?'Panel de preparación':'Readiness Dashboard',uiLanguage==='es'?'Cálculos locales en vivo de competencias, evaluaciones y acciones':'Live local calculations from competency, assessment, and corrective-action records',`<div class="card brain-hero"><span class="brain-chip">Eagle AI · Adaptive local intelligence</span><h2>${uiLanguage==='es'?'Bienvenido de nuevo':'Welcome back'}, ${esc(currentUser.name)}.</h2><p>${interests.length?(uiLanguage==='es'?'Tu enfoque reciente: ':'Your recent focus: ')+interests.map(x=>x[0]).join(' · '):(uiLanguage==='es'?'Eagle AI aprenderá qué información te ayuda más.':'Eagle AI will learn which information helps you most.')}</p></div><div class="kpis"><div class="kpi"><b>${total}</b><span>Active associates</span></div><div class="kpi good"><b>${ready}</b><span>Fully ready</span></div><div class="kpi warn"><b>${open}</b><span>Open actions</span></div><div class="kpi bad"><b>${crit}</b><span>Critical failures</span></div><div class="kpi bad"><b>${overdue}</b><span>Overdue actions</span></div></div><div class="grid"><div class="card"><h3>Shift readiness</h3>${shifts.map(s=>`<div class="shift-row"><b>${s.shift} Shift</b><div class="progress"><span style="width:${s.pct}%"></span></div><span>${s.pct}% · ${s.critical} critical</span></div>`).join('')}</div><div class="card"><h3>Priority attention</h3>${metrics.sort((a,b)=>b.critical-a.critical||b.open-a.open||a.pct-b.pct).slice(0,8).map(x=>`<button class="list-link personOpen" data-emp="${x.employeeNumber}"><span>${esc(x.name)} · ${x.shift} · ${x.assignedLevel}</span><span class="pill ${x.critical?'critical':x.open?'nogo':x.pct>=90?'go':'ne'}">${x.pct}%</span></button>`).join('')}</div></div>`,`<button class="secondary" id="exportDash">Export dashboard CSV</button>`);$$('.personOpen').forEach(b=>b.onclick=()=>personDetail(b.dataset.emp));$('#exportDash').onclick=exportDashboard}
function personnel(){
  page('Personnel Master','Search the central Personnel Master by employee number, name, shift, role, level, status, or qualified line',`<div class="filters"><input id="pSearch" type="search" inputmode="text" enterkeyhint="search" autocomplete="off" autocorrect="off" autocapitalize="none" spellcheck="false" placeholder="Search name or employee #"><select id="pShift"><option value="">All shifts</option>${['A','B','C','D'].map(x=>`<option>${x}</option>`).join('')}</select><select id="pStatus"><option value="">All statuses</option><option>Active</option><option>Leave of Absence</option><option>Inactive</option><option>Terminated</option><option>Vacant</option></select></div><div id="pSearchMeta" class="search-meta"></div><div id="ptable"></div>`,canManagePersonnel()?'<button class="primary" id="addPerson">Add personnel</button>':'');
  const normalizeValue=v=>String(v??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[“”"']/g,'').replace(/[^a-zA-Z0-9\- ]/g,' ').replace(/\s+/g,' ').trim().toLowerCase();
  const numberOnly=v=>String(v??'').replace(/\D/g,'');
  const master=()=>Array.isArray(state.personnel)?state.personnel:[];
  const render=()=>{
    const input=$('#pSearch'); if(!input)return;
    const raw=String(input.value??'');
    const q=normalizeValue(raw), qDigits=numberOnly(raw), shift=$('#pShift').value, status=$('#pStatus').value;
    const tokens=q.split(' ').filter(Boolean);
    const results=master().map(p=>{
      const emp=numberOnly(p.employeeNumber);
      const values=[p.employeeNumber,p.name,p.positionId,p.shift,p.role,p.assignedLevel,p.approvedLevel,p.status,p.qualifiedLines,p.supervisor].map(normalizeValue);
      const name=normalizeValue(p.name), haystack=values.join(' ');
      let score=0;
      if(!q&&!qDigits) score=1;
      if(qDigits){
        if(emp===qDigits) score=Math.max(score,10000);
        else if(emp.startsWith(qDigits)) score=Math.max(score,8000);
        else if(emp.includes(qDigits)) score=Math.max(score,6000);
      }
      if(q){
        if(name===q) score=Math.max(score,9500);
        else if(name.startsWith(q)) score=Math.max(score,7500);
        else if(values.some(v=>v===q)) score=Math.max(score,7000);
        else if(haystack.includes(q)) score=Math.max(score,5000);
        if(tokens.length&&tokens.every(t=>values.some(v=>v.includes(t)))) score=Math.max(score,4500);
      }
      return {p,score};
    }).filter(({p,score})=>score>0&&(!shift||String(p.shift)===shift)&&(!status||String(p.status)===status))
      .sort((a,b)=>{
        const aVacant=String(a.p.status||'').toLowerCase()==='vacant'||(!a.p.name&&!a.p.employeeNumber);
        const bVacant=String(b.p.status||'').toLowerCase()==='vacant'||(!b.p.name&&!b.p.employeeNumber);
        if(aVacant!==bVacant) return aVacant?1:-1;
        if(b.score!==a.score) return b.score-a.score;
        if(!aVacant){
          const nameOrder=String(a.p.name||'').localeCompare(String(b.p.name||''),undefined,{sensitivity:'base'});
          if(nameOrder) return nameOrder;
          return String(a.p.employeeNumber??'').localeCompare(String(b.p.employeeNumber??''),undefined,{numeric:true});
        }
        return String(a.p.positionId||'').localeCompare(String(b.p.positionId||''),undefined,{numeric:true});
      });
    $('#pSearchMeta').textContent=`${results.length} result${results.length===1?'':'s'}${raw.trim()?` for “${raw.trim()}”`:''}`;
    const rows=results.map(({p})=>`<tr><td>${employeePhoto(p,'employee-thumb')}</td><td>${esc(p.employeeNumber)}</td><td><button type="button" class="text-btn pd" data-emp="${esc(p.employeeNumber)}" data-pos="${esc(p.positionId)}">${esc(p.name||p.positionId)}</button></td><td>${esc(p.shift)}</td><td>${esc(p.role)}</td><td><span class="pill ${String(p.status).toLowerCase()}">${esc(p.status)}</span></td><td>${esc(p.assignedLevel)}</td><td>${esc(p.approvedLevel||'—')}</td>${canManagePersonnel()?`<td><div class="row-actions"><button type="button" class="secondary photoBtn" data-pos="${esc(p.positionId)}">${p.photo?'Change photo':'Add photo'}</button><button type="button" class="secondary pe" data-pos="${esc(p.positionId)}">Edit</button></div></td>`:''}</tr>`).join('');
    $('#ptable').innerHTML=results.length?`<div class="table-wrap"><table><thead><tr><th>Photo</th><th>Employee #</th><th>Name</th><th>Shift</th><th>Role</th><th>Status</th><th>Assigned</th><th>Approved</th>${canManagePersonnel()?'<th>Actions</th>':''}</tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="card empty-state"><b>No personnel found</b><p>Try the exact employee number, part of the number, first name, or last name.</p></div>';
    $$('.pd').forEach(b=>b.onclick=()=>openEmployeeProfile(b.dataset.emp||b.dataset.pos));
    $$('.pe,.photoBtn').forEach(b=>b.onclick=()=>personEdit(b.dataset.pos));
  };
  const input=$('#pSearch');
  ['input','change','search','keyup','compositionend'].forEach(eventName=>input.addEventListener(eventName,render));
  input.addEventListener('paste',()=>setTimeout(render,0));
  $('#pShift').addEventListener('change',render); $('#pStatus').addEventListener('change',render);
  if($('#addPerson'))$('#addPerson').onclick=()=>personEdit();
  render();
}
function openEmployeeProfile(identifier){
  const key=String(identifier??'').trim();
  const digits=key.replace(/\D/g,'');
  const normalized=key.toLowerCase();
  const p=(state.personnel||[]).find(x=>
    String(x.employeeNumber??'').trim()===key ||
    (digits&&String(x.employeeNumber??'').replace(/\D/g,'')===digits) ||
    String(x.positionId??'').trim()===key ||
    String(x.name??'').trim().toLowerCase()===normalized
  );
  if(!p){toast('Employee profile not found');return false}
  personDetail(String(p.employeeNumber??'').trim());
  return true;
}
window.openEmployeeProfile=openEmployeeProfile;
function personDetail(emp){const key=String(emp??'').trim();const p=state.personnel.find(x=>String(x.employeeNumber??'').trim()===key);if(!p){toast('Employee profile not found');return}const m=personMetrics(p),hist=state.sessions.filter(s=>String(s.employeeNumber??'').trim()===key).sort((a,b)=>(b.date||'').localeCompare(a.date||''));page(esc(p.name),`${p.shift} Shift · ${p.role} · Employee #${p.employeeNumber}`,`<div class="person-profile">${employeePhoto(p,'employee-photo-large')}<div><h2>${esc(p.name)}</h2><p>${p.shift} Shift · ${esc(p.role)} · Employee #${esc(p.employeeNumber)}</p></div></div><div class="kpis"><div class="kpi"><b>${p.assignedLevel}</b><span>Assigned level</span></div><div class="kpi"><b>${m.highest}</b><span>Highest fully qualified</span></div><div class="kpi"><b>${m.pct}%</b><span>Readiness</span></div><div class="kpi warn"><b>${m.open}</b><span>Open actions</span></div></div><div class="grid"><div class="card"><h3>Authorization status</h3><p><b>Independent performance:</b> ${m.critical||m.open?'Restricted pending closure':'Based on current GO records'}</p><p><b>Qualified lines:</b> ${esc(p.qualifiedLines||'Not assigned')}</p><p><b>Hire date:</b> ${esc(p.hireDate||'Not entered')}</p><p><b>Extrusion assignment:</b> ${esc(p.extrusionDate||p.effectiveDate||'Not entered')}</p><p><b>Supervisor / Sr. Lead:</b> ${esc(p.supervisor||'Not entered')}</p></div><div class="card"><h3>Assessment summary</h3><p>GO: ${m.go} · NO-GO: ${m.nogo} · Assistance: ${m.assist} · Critical: ${m.critical}</p><div class="progress"><span style="width:${m.pct}%"></span></div></div></div><h3>Assessment history</h3>${sessionTable(hist)}`,'<button class="secondary" id="backPeople">Back</button>');$('#backPeople').onclick=personnel}
function personEdit(pos){const p=pos?state.personnel.find(x=>x.positionId===pos):{positionId:uid('POS'),status:'Active',assignedLevel:'-10',shift:'A',role:'Operator',photo:''};const old=clone(p);let pendingPhoto=p.photo||'';modal(`<h2>${pos?'Edit':'Add'} personnel master record</h2><div class="photo-editor"><div id="photoPreview">${employeePhoto(p,'employee-photo-large')}</div><div><label class="photo-upload">Employee photo<input id="mPhoto" type="file" accept="image/*" capture="environment"></label><button class="secondary" id="removePhoto" type="button">Remove photo</button><small>The image is compressed automatically and stored with this local profile.</small></div></div><div class="form-grid"><label>Employee number<input id="mEmp" value="${esc(p.employeeNumber)}"></label><label>Associate name<input id="mName" value="${esc(p.name)}"></label><label>Shift<select id="mShift">${['A','B','C','D'].map(x=>`<option ${p.shift===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Role<select id="mRole">${['Operator','Sr. Lead','Supervisor'].map(x=>`<option ${p.role===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Assigned level<select id="mLevel">${Object.keys(levelRank).map(x=>`<option ${p.assignedLevel===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Employment status<select id="mStatus">${['Active','Leave of Absence','Inactive','Terminated'].map(x=>`<option ${p.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Preferred language<select id="mLang"><option value="en">English</option><option value="es">Español</option></select></label><label>Qualified lines<input id="mLines" value="${esc(p.qualifiedLines)}"></label><label>Hire date<input id="mHire" type="date" value="${esc(p.hireDate)}"></label><label>Extrusion assignment date<input id="mExt" type="date" value="${esc(p.extrusionDate||p.effectiveDate)}"></label><label>Supervisor / Sr. Lead<input id="mSup" value="${esc(p.supervisor)}"></label><label class="full">Notes<textarea id="mNotes">${esc(p.notes)}</textarea></label></div><div class="actions"><button class="primary" id="savePerson">Save master record</button><button class="secondary close">Cancel</button></div>`);$('#mPhoto').onchange=e=>readEmployeePhoto(e.target.files[0],data=>{pendingPhoto=data;$('#photoPreview').innerHTML=data?`<img class="employee-photo-large" src="${data}" alt="Employee photo preview">`:`<div class="employee-photo-large photo-placeholder">?</div>`});$('#removePhoto').onclick=()=>{pendingPhoto='';$('#photoPreview').innerHTML='<div class="employee-photo-large photo-placeholder">?</div>';$('#mPhoto').value=''};$('#savePerson').onclick=()=>{const emp=$('#mEmp').value.trim(),name=$('#mName').value.trim();if(!emp||!name)return toast('Employee number and name are required');const dupe=state.personnel.find(x=>x.employeeNumber===emp&&x.positionId!==p.positionId);if(dupe)return toast('Employee number must be unique');const isNew=!pos;Object.assign(p,{employeeNumber:emp,name,shift:$('#mShift').value,role:$('#mRole').value,assignedLevel:$('#mLevel').value,status:$('#mStatus').value,qualifiedLines:$('#mLines').value,hireDate:$('#mHire').value,extrusionDate:$('#mExt').value,supervisor:$('#mSup').value,notes:$('#mNotes').value,photo:pendingPhoto});if(isNew)state.personnel.push(p);let u=ensureUserForPerson(p);Object.assign(u,{employeeNumber:emp,name,username:isNew?emp:u.username,maxLevel:p.assignedLevel,language:$('#mLang').value,disabled:p.status!=='Active'});if(isNew){u.role='viewer';u.password='RP'+emp;u.mustChange=true;u.manageMetl=false;u.managePersonnel=false}saveUsers();audit(isNew?'CREATE':'UPDATE','Personnel & User',p.employeeNumber,isNew?'Master record and login account created':'Master record revised',old,p);closeModal();if(isNew){const applicableSubs=state.subtasks.filter(x=>x.status==='Active'&&levelRank[x.requiredLevel]<=levelRank[p.assignedLevel]);const taskIds=new Set(applicableSubs.map(x=>x.taskId));modal(`<div class="success-panel"><div class="success-icon">✓</div><h2>Employee successfully created</h2><p>The personnel profile and read-only login account are ready.</p><div class="credential-card"><div><span>Name</span><b>${esc(p.name)}</b></div><div><span>Employee # / Username</span><b>${esc(emp)}</b></div><div><span>Temporary password</span><b>RP${esc(emp)}</b></div><div><span>Status</span><b>${esc(p.status)}</b></div><div><span>Assigned level</span><b>${esc(p.assignedLevel)}</b></div><div><span>METL tasks available</span><b>${taskIds.size}</b></div><div><span>Subtasks available</span><b>${applicableSubs.length}</b></div></div><p class="notice">The employee must change the temporary password at first login. Authority remains read-only until an administrator changes it manually.</p><div class="actions"><button class="primary" id="copyCredentials">Copy credentials</button><button class="secondary" id="finishNewEmployee">Done</button></div></div>`);$('#copyCredentials').onclick=async()=>{const text=`RP IA login\nName: ${p.name}\nUsername: ${emp}\nTemporary password: RP${emp}`;try{await navigator.clipboard.writeText(text);toast('Credentials copied')}catch{toast(`Username ${emp} · Password RP${emp}`)}};$('#finishNewEmployee').onclick=()=>{closeModal();personnel()}}else personnel()}}
function tasks(){page('METL & Subtask Library',`${state.tasks.filter(t=>t.status==='Active').length} active METL tasks · ${state.subtasks.filter(s=>s.status==='Active').length} active supporting subtasks`,`<div class="library-tabs"><button class="tab active" id="taskTab">METL Tasks</button><button class="tab" id="subTab">Subtask Library</button></div><div id="libraryBody"></div>`,canManageMetl()?'<button class="primary" id="newTask">New METL task</button><button class="primary" id="newSubtask">New subtask</button>':'');
const drawTasks=()=>{$('#libraryBody').innerHTML=`<div class="filters"><input id="tSearch" placeholder="Search task, standard, or source"><select id="tLevel"><option value="">All levels</option>${Object.keys(levelRank).map(x=>`<option>${x}</option>`).join('')}</select><select id="tStatus"><option value="Active">Active</option><option value="">All</option><option>Inactive</option><option>Superseded</option></select></div><div id="taskList" class="grid"></div>`;const draw=()=>{const q=$('#tSearch').value.toLowerCase(),lv=$('#tLevel').value,st=$('#tStatus').value;$('#taskList').innerHTML=state.tasks.filter(t=>(t.id+' '+t.name+' '+t.description+' '+t.source).toLowerCase().includes(q)&&(!lv||t.requiredLevel===lv)&&(!st||t.status===st)).map(t=>{const subs=state.subtasks.filter(s=>s.taskId===t.id&&s.status==='Active'),cg=subs.filter(s=>s.criticality==='Critical Gate').length;return`<div class="card"><div class="page-head"><div><h3>${t.id} — ${esc(t.name)}</h3><p>${esc(t.domain)} · ${t.requiredLevel} · Revision ${t.revision||1}</p></div><span class="pill ${String(t.status).toLowerCase()}">${t.status}</span></div><p>${esc(t.description)}</p><small>${subs.length} subtasks · ${cg} Critical Gates · recert ${t.recertMonths||'—'} months</small><div class="actions"><button class="secondary tv" data-id="${t.id}">Open</button>${canManageMetl()?`<button class="secondary te" data-id="${t.id}">Edit</button>`:''}</div></div>`}).join('')||'<div class="card empty-state"><b>No METL tasks found</b></div>';$$('.tv').forEach(b=>b.onclick=()=>taskDetail(b.dataset.id));$$('.te').forEach(b=>b.onclick=()=>taskEdit(b.dataset.id))};['tSearch','tLevel','tStatus'].forEach(id=>$(`#${id}`).oninput=draw);draw()};
const drawSubs=()=>{$('#libraryBody').innerHTML=`<div class="filters"><input id="sSearchAll" placeholder="Search ID, name, standard, evidence, or task"><select id="sTaskAll"><option value="">All METL tasks</option>${state.tasks.filter(t=>t.status==='Active').map(t=>`<option value="${t.id}">${t.id} — ${esc(t.name)}</option>`).join('')}</select><select id="sLevelAll"><option value="">All levels</option>${Object.keys(levelRank).map(x=>`<option>${x}</option>`).join('')}</select><select id="sCritAll"><option value="">All classifications</option><option>Supporting</option><option>Critical Gate</option></select></div><div id="subList" class="subtask-library"></div>`;const draw=()=>{const q=$('#sSearchAll').value.toLowerCase(),tid=$('#sTaskAll').value,lv=$('#sLevelAll').value,cr=$('#sCritAll').value;const rows=state.subtasks.filter(x=>x.status!=='Superseded'&&(!tid||x.taskId===tid)&&(!lv||x.requiredLevel===lv)&&(!cr||x.criticality===cr)&&(x.id+' '+x.name+' '+x.standard+' '+x.evidence+' '+x.taskId).toLowerCase().includes(q));$('#subList').innerHTML=rows.map(x=>`<article class="card subtask-card ${x.criticality==='Critical Gate'?'critical-box':''}"><div class="page-head"><div><b>${esc(x.id)}</b><h3>${esc(x.name)}</h3><small>${esc(x.taskId)} · ${esc(x.requiredLevel)} · ${esc(x.status||'Active')}</small></div><span class="pill ${x.criticality==='Critical Gate'?'critical':'ne'}">${esc(x.criticality||'Supporting')}</span></div><p><b>Standard:</b> ${esc(x.standard||'Not entered')}</p><p><b>Evidence:</b> ${esc(x.evidence||'Not entered')}</p>${canManageMetl()?`<div class="actions"><button class="secondary subEdit" data-task="${x.taskId}" data-id="${x.id}">Edit</button><button class="secondary subClone" data-task="${x.taskId}" data-id="${x.id}">Clone</button><button class="secondary subToggle" data-id="${x.id}">${x.status==='Inactive'?'Activate':'Deactivate'}</button></div>`:''}</article>`).join('')||'<div class="card empty-state"><b>No subtasks found</b><p>Try another filter or add a new subtask.</p></div>';$$('.subEdit').forEach(b=>b.onclick=()=>subtaskEdit(b.dataset.task,b.dataset.id));$$('.subClone').forEach(b=>b.onclick=()=>subtaskEdit(b.dataset.task,b.dataset.id,true));$$('.subToggle').forEach(b=>b.onclick=()=>{const x=state.subtasks.find(s=>s.id===b.dataset.id);const old=clone(x);x.status=x.status==='Inactive'?'Active':'Inactive';audit('UPDATE','Subtask',x.id,`Status changed to ${x.status}`,old,x);draw()})};['sSearchAll','sTaskAll','sLevelAll','sCritAll'].forEach(id=>$(`#${id}`).oninput=draw);draw()};
const activate=(which)=>{const task=which==='task';$('#taskTab').classList.toggle('active',task);$('#subTab').classList.toggle('active',!task);task?drawTasks():drawSubs()};$('#taskTab').onclick=()=>activate('task');$('#subTab').onclick=()=>activate('sub');activate('task');if($('#newTask'))$('#newTask').onclick=()=>taskEdit();if($('#newSubtask'))$('#newSubtask').onclick=()=>subtaskEdit()}
function taskDetail(id){const t=state.tasks.find(x=>x.id===id&&x.status==='Active')||state.tasks.find(x=>x.id===id);const subs=state.subtasks.filter(s=>s.taskId===id&&s.status!=='Superseded').sort((a,b)=>(a.sequence||0)-(b.sequence||0));page(`${t.id} — ${esc(t.name)}`,`${esc(t.domain)} · ${t.requiredLevel} · Revision ${t.revision||1}`,`<div class="card"><p>${esc(t.description)}</p><p><b>Training standard:</b> ${esc(t.trainedStandard)}</p><p><b>Source:</b> ${esc(t.source)}</p></div><div class="section-head"><h3>Supporting subtasks</h3>${canManageMetl()?`<button class="primary" id="addSub">Add subtask</button>`:''}</div><div class="grid">${subs.map(s=>`<div class="card ${s.criticality==='Critical Gate'?'critical-box':''}"><div class="page-head"><div><b>${s.id}</b><p>${esc(s.name)}</p></div><span class="pill ${s.criticality==='Critical Gate'?'critical':'ne'}">${esc(s.criticality)}</span></div><p><b>Level:</b> ${s.requiredLevel} · <b>Evidence:</b> ${esc(s.evidence)}</p><p><b>Standard:</b> ${esc(s.standard)}</p>${canManageMetl()?`<div class="actions"><button class="secondary se" data-id="${s.id}">Edit</button><button class="secondary sc" data-id="${s.id}">Clone</button></div>`:''}</div>`).join('')}</div>`,'<button class="secondary" id="backTask">Back</button>');$('#backTask').onclick=tasks;if($('#addSub'))$('#addSub').onclick=()=>subtaskEdit(id);$$('.se').forEach(b=>b.onclick=()=>subtaskEdit(id,b.dataset.id));$$('.sc').forEach(b=>b.onclick=()=>subtaskEdit(id,b.dataset.id,true))}

function taskEdit(id){const existing=id?state.tasks.find(t=>t.id===id&&t.status==='Active'):null,p=existing?clone(existing):{id:'',name:'',domain:'',requiredLevel:'-10',description:'',trainedStandard:'',recertMonths:12,source:'',status:'Active',revision:1};modal(`<h2>${existing?'Revise':'Create'} METL task</h2><div class="form-grid"><label>Task ID<input id="eId" value="${esc(p.id)}" ${existing?'readonly':''}></label><label>Name<input id="eName" value="${esc(p.name)}"></label><label>Domain<input id="eDomain" value="${esc(p.domain)}"></label><label>Required level<select id="eLevel">${Object.keys(levelRank).map(x=>`<option ${p.requiredLevel===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="full">Description<textarea id="eDesc">${esc(p.description)}</textarea></label><label class="full">Performance / training standard<textarea id="eStd">${esc(p.trainedStandard)}</textarea></label><label>Recertification months<input id="eRecert" type="number" value="${p.recertMonths||12}"></label><label>Source / reference<input id="eSource" value="${esc(p.source)}"></label><label>Status<select id="eStatus">${['Active','Inactive'].map(x=>`<option ${p.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Effective date<input id="eDate" type="date" value="${today()}"></label><label class="full">Revision reason<textarea id="eReason"></textarea></label></div><div class="actions"><button class="primary" id="saveTask">Publish controlled record</button><button class="secondary close">Cancel</button></div>`);$('#saveTask').onclick=()=>{const tid=$('#eId').value.trim(),name=$('#eName').value.trim();if(!tid||!name)return toast('Task ID and name are required');if(!existing&&state.tasks.some(t=>t.id===tid&&t.status==='Active'))return toast('Active Task ID already exists');const data={...p,id:tid,name,domain:$('#eDomain').value,requiredLevel:$('#eLevel').value,description:$('#eDesc').value,trainedStandard:$('#eStd').value,recertMonths:+$('#eRecert').value,source:$('#eSource').value,status:$('#eStatus').value,effectiveDate:$('#eDate').value,revisionReason:$('#eReason').value};if(existing){existing.status='Superseded';data.revision=(existing.revision||1)+1;data.previousRevision=existing.revision||1;state.tasks.push(data);audit('REVISE','METL Task',tid,`Revision ${data.revision} published`,existing,data)}else{state.tasks.push(data);audit('CREATE','METL Task',tid,'Controlled task created',null,data)}closeModal();tasks()}}
function subtaskEdit(taskId='',id='',cloneMode=false){const source=id?state.subtasks.find(s=>s.id===id):null,old=source&&!cloneMode?source:null;const defaultTask=taskId||state.tasks.find(t=>t.status==='Active')?.id||'';const p=source?clone(source):{id:'',taskId:defaultTask,sequence:state.subtasks.filter(s=>s.taskId===defaultTask).length+1,requiredLevel:'-10',criticality:'Supporting',status:'Active',name:'',standard:'',evaluationMethod:'Direct Observation',evidence:'',source:'',retrainingInterval:'',reassessmentInterval:'',srLeadVerification:false,independentAuthorization:false};if(cloneMode){p.id='';p.name=(p.name||'')+' (Copy)'}modal(`<h2>${old?'Revise':cloneMode?'Clone':'Create'} supporting subtask</h2><div class="form-grid"><label>Parent METL task<select id="sTask">${state.tasks.filter(t=>t.status==='Active').map(t=>`<option value="${t.id}" ${p.taskId===t.id?'selected':''}>${t.id} — ${esc(t.name)}</option>`).join('')}</select></label><label>Subtask ID<input id="sId" value="${esc(p.id)}" ${old?'readonly':''} placeholder="Example: M04-017"></label><label>Sequence<input id="sSeq" type="number" value="${p.sequence||1}"></label><label>Qualification level<select id="sLevel">${Object.keys(levelRank).map(x=>`<option ${p.requiredLevel===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="full">Subtask name<textarea id="sName">${esc(p.name)}</textarea></label><label>Criticality<select id="sCritical"><option ${p.criticality==='Supporting'?'selected':''}>Supporting</option><option ${p.criticality==='Critical Gate'?'selected':''}>Critical Gate</option></select></label><label>Status<select id="sStatus"><option ${p.status!=='Inactive'?'selected':''}>Active</option><option ${p.status==='Inactive'?'selected':''}>Inactive</option></select></label><label>Evaluation method<input id="sMethod" value="${esc(p.evaluationMethod)}"></label><label>Training source / reference<input id="sSource" value="${esc(p.source)}"></label><label class="full">Performance standard<textarea id="sStd">${esc(p.standard)}</textarea></label><label class="full">Required evidence<textarea id="sEvidence">${esc(p.evidence)}</textarea></label><label>Retraining interval<input id="sRetrain" value="${esc(p.retrainingInterval)}"></label><label>Reassessment interval<input id="sReassess" value="${esc(p.reassessmentInterval)}"></label><label>Sr. Lead verification<select id="sVerify"><option value="false" ${!p.srLeadVerification?'selected':''}>No</option><option value="true" ${p.srLeadVerification?'selected':''}>Yes</option></select></label><label>Independent performance<select id="sInd"><option value="false" ${!p.independentAuthorization?'selected':''}>No</option><option value="true" ${p.independentAuthorization?'selected':''}>Yes</option></select></label><label class="full">Revision reason / notes<textarea id="sReason">${esc(p.revisionNote)}</textarea></label></div><div class="actions"><button class="primary" id="saveSub">${old?'Save revision':'Add subtask'}</button><button class="secondary close">Cancel</button></div>`);$('#sTask').onchange=()=>{if(!old&&!$('#sId').value.trim()){const t=$('#sTask').value,n=state.subtasks.filter(x=>x.taskId===t).length+1;$('#sId').value=t+'-'+String(n).padStart(3,'0')}};$('#sTask').dispatchEvent(new Event('change'));$('#saveSub').onclick=()=>{const data={...p,taskId:$('#sTask').value,id:$('#sId').value.trim(),sequence:+$('#sSeq').value,name:$('#sName').value.trim(),requiredLevel:$('#sLevel').value,criticality:$('#sCritical').value,status:$('#sStatus').value,evaluationMethod:$('#sMethod').value,source:$('#sSource').value,standard:$('#sStd').value,evidence:$('#sEvidence').value,retrainingInterval:$('#sRetrain').value,reassessmentInterval:$('#sReassess').value,srLeadVerification:$('#sVerify').value==='true',independentAuthorization:$('#sInd').value==='true',revisionNote:$('#sReason').value};if(!data.taskId||!data.id||!data.name)return toast('Parent task, Subtask ID, and name are required');if(!old&&state.subtasks.some(x=>x.id===data.id))return toast('Subtask ID already exists');if(old){const before=clone(old);Object.assign(old,data);audit('UPDATE','Subtask',old.id,'Controlled subtask revised',before,old)}else{state.subtasks.push(data);audit('CREATE','Subtask',data.id,cloneMode?'Subtask cloned':'Controlled subtask created',null,data)}closeModal();tasks()}}

function matrixView(){const people=activePeople(),tasks=state.tasks.filter(t=>t.status==='Active');page('Readiness Matrix','Calculated from current assessment results; higher levels include all lower-level requirements',`<div class="filters"><select id="mxShift"><option value="">All shifts</option>${['A','B','C','D'].map(x=>`<option>${x}</option>`).join('')}</select><input id="mxSearch" placeholder="Search name, employee #, shift, role, or level"></div><div id="mxTable"></div>`);const draw=()=>{const sh=$('#mxShift').value,q=$('#mxSearch').value,rows=people.filter(p=>(!sh||p.shift===sh)&&SearchEngine.matchPerson(p,q));$('#mxTable').innerHTML=`<div class="table-wrap matrix-table"><table><thead><tr><th>Associate</th><th>Shift</th><th>Role</th><th>Assigned</th><th>Highest qualified</th>${tasks.map(t=>`<th>${t.id}</th>`).join('')}<th>Readiness</th></tr></thead><tbody>${rows.map(p=>{const m=personMetrics(p),latest=latestResults(p.employeeNumber);return`<tr><td>${esc(p.name)}</td><td>${p.shift}</td><td>${p.role}</td><td>${p.assignedLevel}</td><td>${m.highest}</td>${tasks.map(t=>{const subs=state.subtasks.filter(s=>s.taskId===t.id&&s.status==='Active'&&levelRank[s.requiredLevel]<=levelRank[p.assignedLevel]);const vals=subs.map(s=>latest.get(p.employeeNumber+'|'+s.id)?.result||'NE');let r=vals.length&&vals.every(x=>x==='GO')?'GO':vals.some(x=>x==='NO-GO')?'NO-GO':vals.some(x=>x==='REQUIRES ASSISTANCE')?'ASSIST':'NE';return`<td><span class="pill ${r==='GO'?'go':r==='NO-GO'?'nogo':r==='ASSIST'?'warn':'ne'}">${r}</span></td>`}).join('')}<td>${m.pct}%</td></tr>`}).join('')}</tbody></table></div>`};$('#mxShift').oninput=draw;$('#mxSearch').oninput=draw;draw()}
function assess(){const people=activePeople(),tasks=state.tasks.filter(t=>t.status==='Active');page('Assessment Session','Approved evaluator authority, Critical Gates, evidence, and historical preservation are enforced',`<div class="card form-grid"><label>Associate<select id="aPerson"><option value="">Select associate</option>${people.map(p=>`<option value="${p.employeeNumber}">${esc(p.name)} · ${p.shift} · ${p.assignedLevel}</option>`).join('')}</select></label><label>METL task<select id="aTask"><option value="">Select task</option>${tasks.map(t=>`<option value="${t.id}">${t.id} — ${esc(t.name)} (${t.requiredLevel})</option>`).join('')}</select></label><label>Evaluation date<input id="aDate" type="date" value="${today()}"></label><label>Method<select id="aMethod">${['Hands-On','Direct Observation','Oral Questioning','Written Test','Simulation','Document Review','Combined'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Production line / location<input id="aLine"></label><label>Session notes<input id="aNotes"></label></div><div id="evalSubs"></div>`);$('#aPerson').onchange=drawAssessment;$('#aTask').onchange=drawAssessment}
function drawAssessment(){const emp=$('#aPerson').value,tid=$('#aTask').value;if(!emp||!tid)return $('#evalSubs').innerHTML='';const p=state.personnel.find(x=>x.employeeNumber===emp),t=state.tasks.find(x=>x.id===tid);if(levelRank[t.requiredLevel]>levelRank[currentUser.maxLevel||'-40'])return $('#evalSubs').innerHTML='<div class="card bad">Evaluator is not authorized for this qualification level.</div>';const subs=state.subtasks.filter(s=>s.taskId===tid&&s.status==='Active'&&levelRank[s.requiredLevel]<=levelRank[p.assignedLevel]);$('#evalSubs').innerHTML=`<h3>${subs.length} applicable subtasks</h3>${subs.map(s=>`<div class="subtask-eval ${s.criticality==='Critical Gate'?'critical-box':''}" data-sub="${s.id}"><div class="page-head"><div><h4>${s.id}</h4><p>${esc(s.name)}</p></div>${s.criticality==='Critical Gate'?'<span class="pill critical">Critical Gate</span>':''}</div><p><b>Standard:</b> ${esc(s.standard)}</p><p><b>Required evidence:</b> ${esc(s.evidence)}</p><div class="form-grid"><label>Rating<select class="r"><option>NOT EVALUATED</option><option>GO</option><option>NO-GO</option><option>REQUIRES ASSISTANCE</option><option>SUSPENDED</option></select></label><label>Evidence reference<input class="ev" placeholder="Photo, document, test, observation"></label><label class="full">Evaluator observations<textarea class="obs"></textarea></label>${s.srLeadVerification?'<label>Sr. Lead verification<select class="verify"><option value="">Pending</option><option>Verified</option><option>Not Verified</option></select></label>':''}</div></div>`).join('')}<div class="card form-grid"><label>Retraining required<select id="aRetrain"><option>No</option><option>Yes</option></select></label><label>Reassessment date<input id="aReDate" type="date"></label><label class="full">Corrective action summary<textarea id="aCorrective"></textarea></label></div><button class="primary" id="submitAssessment">Sign and submit assessment</button>`;$('#submitAssessment').onclick=submitAssessment}
function submitAssessment(){const emp=$('#aPerson').value,tid=$('#aTask').value,p=state.personnel.find(x=>x.employeeNumber===emp),t=state.tasks.find(x=>x.id===tid),sid=uid('ASMT');const rows=$$('.subtask-eval').map(box=>{const s=state.subtasks.find(x=>x.id===box.dataset.sub);return{subtaskId:s.id,subtaskName:s.name,criticality:s.criticality,requiredLevel:s.requiredLevel,result:box.querySelector('.r').value,evidenceReference:box.querySelector('.ev').value,observation:box.querySelector('.obs').value,srLeadVerification:box.querySelector('.verify')?.value||''}});if(rows.every(r=>r.result==='NOT EVALUATED'))return toast('Evaluate at least one subtask');const criticalFail=rows.some(r=>r.criticality==='Critical Gate'&&r.result!=='GO'&&r.result!=='NOT EVALUATED');const noGo=rows.some(r=>r.result==='NO-GO'),assist=rows.some(r=>r.result==='REQUIRES ASSISTANCE');const finalStatus=criticalFail?'UNQUALIFIED — CRITICAL GATE':noGo?'UNQUALIFIED':assist?'REQUIRES ASSISTANCE':'RECORDED';const session={id:sid,employeeNumber:emp,associateName:p.name,shift:p.shift,role:p.role,assignedLevel:p.assignedLevel,taskId:tid,taskName:t.name,taskRevision:t.revision,date:$('#aDate').value,evaluatorName:currentUser.name,evaluatorUsername:currentUser.username,method:$('#aMethod').value,status:'Closed',location:$('#aLine').value,notes:$('#aNotes').value,finalStatus,retrainingRequired:$('#aRetrain').value,reassessmentDate:$('#aReDate').value,correctiveAction:$('#aCorrective').value,signature:`${currentUser.name} · ${new Date().toLocaleString()}`};state.sessions.push(session);for(const r of rows){state.results.push({sessionId:sid,employeeNumber:emp,associateName:p.name,shift:p.shift,role:p.role,taskId:tid,taskName:t.name,date:session.date,evaluatorName:currentUser.name,...r,recordStatus:'Historical'});if(['NO-GO','SUSPENDED'].includes(r.result)||(r.criticality==='Critical Gate'&&r.result==='REQUIRES ASSISTANCE')){const due=$('#aReDate').value||new Date(Date.now()+state.settings.defaultCorrectiveActionDays*86400000).toISOString().slice(0,10);state.actions.push({id:uid('CA'),employeeNumber:emp,employee:p.name,shift:p.shift,taskId:tid,subtaskId:r.subtaskId,standardNotMet:r.observation||r.subtaskName,immediateCoaching:'',requiredRetraining:$('#aCorrective').value||'Targeted retraining required',responsibleTrainer:currentUser.name,targetDate:due,reassessmentDate:$('#aReDate').value,reassessmentResult:'',status:'Open',criticality:r.criticality,created:new Date().toISOString(),createdBy:currentUser.name})}}audit('SUBMIT','Assessment',sid,`${p.name} / ${tid} / ${finalStatus}`,null,session);toast(criticalFail?'Saved — Critical Gate blocks qualification':'Assessment saved and signed');sessionHistory()}
function sessionTable(rows){return`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Associate</th><th>Task</th><th>Evaluator</th><th>Method</th><th>Final status</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr><td>${esc(s.date)}</td><td>${esc(s.associateName)}</td><td>${s.taskId} — ${esc(s.taskName)}</td><td>${esc(s.evaluatorName)}</td><td>${esc(s.method)}</td><td><span class="pill ${String(s.finalStatus).includes('CRITICAL')?'critical':String(s.finalStatus).includes('UNQUALIFIED')?'nogo':'go'}">${esc(s.finalStatus||s.status)}</span></td><td><button class="secondary sv" data-id="${s.id}">View</button></td></tr>`).join('')||'<tr><td colspan="7">No assessment sessions.</td></tr>'}</tbody></table></div>`}
function sessionHistory(){const rows=[...state.sessions].sort((a,b)=>(b.date||'').localeCompare(a.date||''));page('Assessment History','Signed sessions remain preserved; reassessments are separate records',`<div class="filters"><input id="hSearch" placeholder="Search associate, task, evaluator"><select id="hResult"><option value="">All results</option><option>UNQUALIFIED</option><option>CRITICAL</option><option>RECORDED</option></select></div><div id="hTable"></div>`,'<button class="secondary" id="exportAssess">Export assessments CSV</button>');const draw=()=>{const q=$('#hSearch').value.toLowerCase(),r=$('#hResult').value;const f=rows.filter(s=>(s.associateName+' '+s.taskId+' '+s.taskName+' '+s.evaluatorName).toLowerCase().includes(q)&&(!r||String(s.finalStatus).includes(r)));$('#hTable').innerHTML=sessionTable(f);$$('.sv').forEach(b=>b.onclick=()=>sessionDetail(b.dataset.id))};$('#hSearch').oninput=draw;$('#hResult').oninput=draw;draw();$('#exportAssess').onclick=exportAssessments}
function sessionDetail(id){const s=state.sessions.find(x=>x.id===id),rows=state.results.filter(r=>r.sessionId===id);page(`Assessment ${s.id}`,`${s.date} · ${esc(s.associateName)} · ${s.taskId}`,`<div class="card"><p><b>Evaluator:</b> ${esc(s.evaluatorName)} · <b>Method:</b> ${esc(s.method)} · <b>Location:</b> ${esc(s.location)}</p><p><b>Final status:</b> ${esc(s.finalStatus)}</p><p><b>Signature:</b> ${esc(s.signature)}</p><p><b>Reassessment:</b> ${esc(s.reassessmentDate||'Not scheduled')}</p></div><div class="table-wrap"><table><thead><tr><th>Subtask</th><th>Criticality</th><th>Result</th><th>Evidence</th><th>Observation</th><th>Verification</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.subtaskId} — ${esc(r.subtaskName)}</td><td>${esc(r.criticality)}</td><td>${esc(r.result)}</td><td>${esc(r.evidenceReference)}</td><td>${esc(r.observation)}</td><td>${esc(r.srLeadVerification)}</td></tr>`).join('')}</tbody></table></div>`,'<button class="secondary" id="backHist">Back</button>');$('#backHist').onclick=sessionHistory}
function correctiveActionRepository(){
  reconcileCriticalGateActions();
  if(!Array.isArray(state.actions))state.actions=[];
  let changed=false;
  for(const a of state.actions){
    if(!a.id){a.id=uid('CA');changed=true}
    const person=state.personnel.find(p=>String(p.employeeNumber||'')===String(a.employeeNumber||''));
    if(!a.employee&&person?.name){a.employee=person.name;changed=true}
    const rawStatus=String(a.status||'').trim().toLowerCase();const normalizedStatus=rawStatus==='closed'?'Closed':rawStatus==='upcoming'?'Upcoming':'Open';
    if(a.status!==normalizedStatus){a.status=normalizedStatus;changed=true}
    if(!a.criticality)a.criticality='Supporting';
  }
  if(changed)save();
  return [...state.actions].sort((a,b)=>(a.status==='Closed')-(b.status==='Closed')||(a.targetDate||'9999-12-31').localeCompare(b.targetDate||'9999-12-31')||(a.created||'').localeCompare(b.created||''));
}

window.correctiveActionRepository=correctiveActionRepository;

function actions(focusActionId=''){
  const rows=correctiveActionRepository();
  page('Corrective Actions & Reassessment','Original failed assessments remain unchanged; closure requires demonstrated competency',`<div class="filters"><select id="caStatus"><option value="">All statuses</option><option>Open</option><option>Upcoming</option><option>Closed</option></select><input id="caSearch" placeholder="Search associate or task"></div><div id="caTable"></div>`);
  const draw=()=>{
    const st=$('#caStatus').value,q=String($('#caSearch').value||'').toLowerCase().trim();
    const f=rows.filter(a=>(!st||a.status===st)&&(`${a.employee||''} ${a.employeeNumber||''} ${a.taskId||''} ${a.subtaskId||''} ${a.id||''}`).toLowerCase().includes(q));
    $('#caTable').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Associate</th><th>Task / Subtask</th><th>Due</th><th>Criticality</th><th>Status</th><th>Owner</th><th></th></tr></thead><tbody>${f.map(a=>`<tr class="${String(a.id)===String(focusActionId)?'focused-row':''}" data-action-row="${esc(a.id)}"><td>${esc(a.employee||'Unknown associate')}</td><td>${esc(a.taskId)} / ${esc(a.subtaskId)}</td><td class="${a.status!=='Closed'&&a.targetDate&&a.targetDate<today()?'overdue':''}">${esc(a.targetDate||'')}</td><td><span class="pill ${a.criticality==='Critical Gate'?'critical':'ne'}">${esc(a.criticality)}</span></td><td><span class="pill ${a.status==='Closed'?'go':a.status==='Upcoming'?'ne':'nogo'}">${esc(a.status)}</span></td><td>${esc(a.responsibleTrainer||a.owner||'')}</td><td><button class="secondary cav" data-id="${esc(a.id)}">Open</button></td></tr>`).join('')||'<tr><td colspan="7">No corrective actions.</td></tr>'}</tbody></table></div>`;
    $$('.cav').forEach(b=>b.onclick=()=>actionDetail(b.dataset.id));
  };
  $('#caStatus').oninput=draw;$('#caSearch').oninput=draw;draw();
  if(focusActionId){
    const target=rows.find(a=>String(a.id)===String(focusActionId));
    if(target)setTimeout(()=>actionDetail(target.id),0);else toast('Corrective action not found');
  }
}
function actionDetail(id){const a=state.actions.find(x=>x.id===id);modal(`<h2>Corrective Action ${a.id}</h2><div class="form-grid"><label>Associate<input value="${esc(a.employee)}" readonly></label><label>Task / Subtask<input value="${a.taskId} / ${a.subtaskId}" readonly></label><label class="full">Standard not met<textarea id="caStd">${esc(a.standardNotMet||a.observation)}</textarea></label><label class="full">Immediate coaching<textarea id="caCoach">${esc(a.immediateCoaching)}</textarea></label><label class="full">Required retraining<textarea id="caTrain">${esc(a.requiredRetraining)}</textarea></label><label>Responsible trainer<input id="caOwner" value="${esc(a.responsibleTrainer||a.owner)}"></label><label>Target completion<input id="caDue" type="date" value="${esc(a.targetDate)}"></label><label>Reassessment date<input id="caRe" type="date" value="${esc(a.reassessmentDate)}"></label><label>Reassessment result<select id="caResult"><option></option>${['GO','NO-GO','REQUIRES ASSISTANCE'].map(x=>`<option ${a.reassessmentResult===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="actions"><button class="primary" id="saveCA">Save</button>${a.status!=='Closed'?'<button class="secondary" id="closeCA">Close after demonstrated competency</button>':''}<button class="secondary close">Cancel</button></div>`);$('#saveCA').onclick=()=>{const old=clone(a);Object.assign(a,{standardNotMet:$('#caStd').value,immediateCoaching:$('#caCoach').value,requiredRetraining:$('#caTrain').value,responsibleTrainer:$('#caOwner').value,targetDate:$('#caDue').value,reassessmentDate:$('#caRe').value,reassessmentResult:$('#caResult').value});audit('UPDATE','Corrective Action',a.id,'Action plan updated',old,a);closeModal();actions()};if($('#closeCA'))$('#closeCA').onclick=()=>{if($('#caResult').value!=='GO')return toast('A GO reassessment is required before closure');const old=clone(a);Object.assign(a,{reassessmentResult:'GO',status:'Closed',closureDate:new Date().toISOString(),closedBy:currentUser.name,closureAuthority:currentUser.maxLevel});audit('CLOSE','Corrective Action',a.id,'Closed after GO reassessment',old,a);closeModal();actions()}}
function buildNotifications(){
  const n=[],now=today();
  for(const a of correctiveActionRepository())if(a.status!=='Closed'){
    if(a.targetDate&&a.targetDate<now)n.push({type:'Overdue Corrective Action',severity:'high',text:`${a.employee} — ${a.taskId}/${a.subtaskId} was due ${a.targetDate}`,recordType:'correctiveAction',recordId:a.id});
    else n.push({type:'Open Corrective Action',severity:a.criticality==='Critical Gate'?'high':'medium',text:`${a.employee} — ${a.taskId}/${a.subtaskId}`,recordType:'correctiveAction',recordId:a.id});
  }
  for(const s of state.sessions)if(s.reassessmentDate&&s.reassessmentDate<=new Date(Date.now()+state.settings.reassessmentWarningDays*86400000).toISOString().slice(0,10))n.push({type:'Reassessment Due',severity:s.reassessmentDate<now?'high':'medium',text:`${s.associateName} — ${s.taskId} due ${s.reassessmentDate}`,recordType:'assessment',recordId:s.id});
  return n;
}
function notificationView(){
  const items=buildNotifications();
  const high=items.filter(n=>n.severity==='high').length;
  const medium=items.filter(n=>n.severity==='medium').length;
  page(
    uiLanguage==='es'?'Notificaciones':'Notifications',
    uiLanguage==='es'?'Acciones, reevaluaciones y alertas que requieren atención':'Corrective actions, reassessments, and alerts requiring attention',
    `<div class="kpis"><div class="kpi bad"><b>${high}</b><span>${uiLanguage==='es'?'Alta prioridad':'High priority'}</span></div><div class="kpi warn"><b>${medium}</b><span>${uiLanguage==='es'?'Próximas':'Upcoming'}</span></div><div class="kpi"><b>${items.length}</b><span>${uiLanguage==='es'?'Total':'Total'}</span></div></div><div class="card"><h3>${uiLanguage==='es'?'Centro de notificaciones':'Notification center'}</h3>${items.length?items.map((n,i)=>`<button class="list-link notificationItem" data-index="${i}"><span><b>${esc(n.type)}</b><small>${esc(n.text)}</small></span><span class="pill ${n.severity==='high'?'critical':'ne'}">${n.severity==='high'?(uiLanguage==='es'?'Urgente':'Urgent'):(uiLanguage==='es'?'Próxima':'Upcoming')}</span></button>`).join(''):`<div class="empty-state"><b>${uiLanguage==='es'?'Todo al día':'All caught up'}</b><p>${uiLanguage==='es'?'No hay alertas activas en este momento.':'There are no active alerts right now.'}</p></div>`}</div>`
  );
  $$('.notificationItem').forEach(btn=>btn.onclick=()=>{
    const n=items[Number(btn.dataset.index)];
    if(!n)return;
    if(n.recordType==='correctiveAction'&&n.recordId)return actions(n.recordId);
    if(n.recordType==='assessment'&&n.recordId)return sessionDetail(n.recordId);
    if(n.type.includes('Corrective'))return actions();
    if(n.type.includes('Reassessment'))return sessionHistory();
  });
}



function auditView(){
  const rows=[...(state.audit||[])];
  page(
    uiLanguage==='es'?'Registro de auditoría':'Audit Trail',
    uiLanguage==='es'?'Historial preservado de cambios, accesos y acciones administrativas':'Preserved history of changes, access, and administrative actions',
    `<div class="filters"><input id="auditSearch" type="search" placeholder="${uiLanguage==='es'?'Buscar usuario, entidad o detalle':'Search user, entity, or detail'}"><select id="auditAction"><option value="">${uiLanguage==='es'?'Todas las acciones':'All actions'}</option>${[...new Set(rows.map(r=>r.action).filter(Boolean))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div id="auditTable"></div>`,
    `<button class="secondary" id="exportAudit">${uiLanguage==='es'?'Exportar auditoría CSV':'Export audit CSV'}</button>`
  );
  const draw=()=>{
    const q=String($('#auditSearch').value||'').toLowerCase().trim();
    const action=$('#auditAction').value;
    const filtered=rows.filter(r=>{
      const hay=[r.time,r.user,r.action,r.entity,r.id,r.detail].map(v=>String(v||'')).join(' ').toLowerCase();
      return(!q||hay.includes(q))&&(!action||r.action===action);
    });
    $('#auditTable').innerHTML=`<div class="table-wrap"><table><thead><tr><th>${uiLanguage==='es'?'Fecha y hora':'Date & time'}</th><th>${uiLanguage==='es'?'Usuario':'User'}</th><th>${uiLanguage==='es'?'Acción':'Action'}</th><th>${uiLanguage==='es'?'Entidad':'Entity'}</th><th>ID</th><th>${uiLanguage==='es'?'Detalle':'Detail'}</th></tr></thead><tbody>${filtered.map(r=>`<tr><td>${esc(r.time||'')}</td><td>${esc(r.user||'System')}</td><td><span class="pill ne">${esc(r.action||'')}</span></td><td>${esc(r.entity||'')}</td><td>${esc(r.id||'')}</td><td>${esc(r.detail||'')}</td></tr>`).join('')||`<tr><td colspan="6">${uiLanguage==='es'?'No hay registros de auditoría.':'No audit records found.'}</td></tr>`}</tbody></table></div>`;
  };
  $('#auditSearch').oninput=draw;
  $('#auditAction').onchange=draw;
  draw();
  $('#exportAudit').onclick=()=>{
    const header=['Time','User','Action','Entity','ID','Detail','Before','After'];
    const data=[header,...rows.map(r=>[r.time,r.user,r.action,r.entity,r.id,r.detail,JSON.stringify(r.before??''),JSON.stringify(r.after??'')])];
    download(csv(data),`RP-IA-audit-${today()}.csv`);
  };
}

function aiShiftSummary(shift){const people=activePeople().filter(p=>!shift||p.shift===shift),m=people.map(p=>({...p,...personMetrics(p)}));const avg=m.length?Math.round(m.reduce((a,x)=>a+x.pct,0)/m.length):0;const open=m.reduce((a,x)=>a+x.open,0),critical=m.reduce((a,x)=>a+x.critical,0);const top=[...m].sort((a,b)=>b.pct-a.pct).slice(0,3),risk=[...m].sort((a,b)=>b.critical-a.critical||b.open-a.open||a.pct-b.pct).slice(0,4);return{people:m,avg,open,critical,top,risk}}
function aiGapRows(emp){const p=state.personnel.find(x=>x.employeeNumber===emp);if(!p)return[];const latest=latestResults(emp);return state.subtasks.filter(x=>x.status==='Active'&&levelRank[x.requiredLevel]<=levelRank[p.assignedLevel]).map(x=>({s:x,r:latest.get(emp+'|'+x.id)})).filter(x=>x.r?.result!=='GO').sort((a,b)=>(b.s.criticality==='Critical Gate')-(a.s.criticality==='Critical Gate')||levelRank[a.s.requiredLevel]-levelRank[b.s.requiredLevel])}
function aiPersonNarrative(p){const m=personMetrics(p),g=aiGapRows(p.employeeNumber),crit=g.filter(x=>x.s.criticality==='Critical Gate'),due=state.actions.filter(a=>a.employeeNumber===p.employeeNumber&&a.status!=='Closed');const next={'-10':'-20','-20':'-30','-30':'-40','-40':'-40'}[p.assignedLevel]||'-10';let status=m.critical?'Not authorized for affected critical work':m.open?'Developing — corrective action open':m.pct===100?'Ready at assigned level':m.pct>=80?'Near qualification':'Training in progress';let rec=crit.length?`Reassess critical gate ${crit[0].s.id} before independent performance.`:due.length?`Complete ${due.length} open corrective action${due.length===1?'':'s'} before qualification review.`:g.length?`Prioritize ${g.slice(0,3).map(x=>x.s.id).join(', ')} next.`:`Review readiness for advancement toward ${next}.`;return{m,g,crit,due,status,rec}}
function aiCoverage(){const keySubs=state.subtasks.filter(s=>s.status==='Active'&&(s.criticality==='Critical Gate'||/die|startup|shutdown|screen|lockout|laser|knife|isobutane|co2/i.test((s.name||'')+' '+(s.standard||'')))).slice(0,30);const latest=latestResults();const rows=[];for(const sh of ['A','B','C','D'])for(const sub of keySubs){const ppl=activePeople().filter(p=>p.shift===sh&&levelRank[sub.requiredLevel]<=levelRank[p.assignedLevel]);const qualified=ppl.filter(p=>latest.get(p.employeeNumber+'|'+sub.id)?.result==='GO');if(qualified.length<=1)rows.push({shift:sh,sub,count:qualified.length,names:qualified.map(x=>x.name)})}return rows.sort((a,b)=>a.count-b.count).slice(0,20)}
function answerMetl(q){const raw=String(q||'').trim();if(!raw)return uiLanguage==='es'?'Pregúntame por una persona, turno, tarea, acción vencida, Critical Gate o avance de nivel.':'Ask about an associate, shift, task, overdue action, Critical Gate, or advancement.';const clean=raw.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const es=/\b(quien|cual|muestra|turno|necesita|vencid|compar|puede|falta|entren|listo|promocion|riesgo|acciones)\b/.test(clean);let sh=(clean.match(/(?:shift|turno)\s*([abcd])/i)||[])[1]?.toUpperCase()||rpConversation.shift;const level=(clean.match(/-(10|20|30|40)\b/)||[])[0]||rpConversation.level;const named=activePeople().find(p=>clean.includes((p.name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase())||new RegExp(`\\b${String(p.employeeNumber)}\\b`).test(clean));if(named){rpConversation.employeeNumber=named.employeeNumber;rpConversation.lastIntent='person'}const person=named||activePeople().find(p=>p.employeeNumber===rpConversation.employeeNumber);const isFollow=/^(y |and |ahora|de esos|those|solo|only|what about|que tal)/.test(clean);let answer='';
if(/compar|compare/.test(clean)&&(/[abcd]/.test(clean))){const letters=[...clean.matchAll(/(?:shift|turno)?\s*([abcd])\b/g)].map(x=>x[1].toUpperCase());if(letters.length>=2){const a=aiShiftSummary(letters[0]),b=aiShiftSummary(letters[1]),winner=a.avg===b.avg?'Both shifts are tied':`${a.avg>b.avg?letters[0]:letters[1]} Shift currently leads`;answer=es?`${letters[0]} tiene ${a.avg}% de preparación y ${letters[1]} tiene ${b.avg}%. ${winner}. La mayor oportunidad está en el turno con más acciones o Critical Gates abiertos.`:`${letters[0]} Shift is ${a.avg}% ready and ${letters[1]} Shift is ${b.avg}% ready. ${winner}. Focus first on the shift with more open actions or Critical Gate failures.`}}
if(!answer&&(/weak|strong|readiness|preparacion|turno|shift/.test(clean)&&sh)){rpConversation.shift=sh;rpConversation.lastIntent='shift';const x=aiShiftSummary(sh);answer=es?`El turno ${sh} tiene ${x.avg}% de preparación, ${x.people.length} empleados activos, ${x.open} acciones abiertas y ${x.critical} fallas críticas. Prioridad: ${x.risk.slice(0,3).map(p=>p.name+' ('+p.pct+'%)').join(', ')||'ninguna'}.`:`${sh} Shift readiness is ${x.avg}%. It has ${x.people.length} active associates, ${x.open} open actions, and ${x.critical} critical failures. Priority attention: ${x.risk.slice(0,3).map(p=>p.name+' ('+p.pct+'%)').join(', ')||'none'}.`}
if(!answer&&(/overdue|vencid/.test(clean)||(isFollow&&rpConversation.lastIntent==='overdue'))){rpConversation.lastIntent='overdue';const a=state.actions.filter(x=>x.status!=='Closed'&&x.targetDate&&x.targetDate<today()&&(!sh||x.shift===sh));answer=a.length?(es?`${a.length} acciones correctivas vencidas: `:`${a.length} overdue corrective actions: `)+a.slice(0,8).map(x=>`${x.employee} — ${x.taskId}/${x.subtaskId} (${x.targetDate})`).join('; '):(es?'No hay acciones correctivas vencidas con esos filtros.':'There are no overdue corrective actions with those filters.')}
if(!answer&&(/critical|gate|critica/.test(clean)||(isFollow&&rpConversation.lastIntent==='critical'))){rpConversation.lastIntent='critical';const rows=activePeople().filter(p=>!sh||p.shift===sh).map(p=>({p,...personMetrics(p)})).filter(x=>x.critical);answer=rows.length?(es?`${rows.length} empleados tienen fallas de Critical Gate: `:`${rows.length} associates have Critical Gate failures: `)+rows.slice(0,8).map(x=>`${x.p.name} (${x.p.shift}, ${x.critical})`).join('; '):(es?'No se encontraron fallas activas de Critical Gate.':'No active Critical Gate failures were found.')}
if(!answer&&(/coverage|cover|cobertura|independent|die move|riesgo/.test(clean)||(isFollow&&rpConversation.lastIntent==='coverage'))){rpConversation.lastIntent='coverage';const r=aiCoverage().filter(x=>!sh||x.shift===sh);answer=r.length?(es?'Riesgos actuales de cobertura: ':'Current coverage risks: ')+r.slice(0,8).map(x=>`${x.shift} — ${x.sub.id} ${x.sub.name}: ${x.count}`).join('; '):(es?'No se detectaron riesgos de cobertura con esos filtros.':'No coverage risks were detected with those filters.')}
if(!answer&&person){const a=aiPersonNarrative(person);rpConversation.employeeNumber=person.employeeNumber;rpConversation.lastIntent='person';if(/falta|need|needs|improve|mejorar|next|siguiente|training|entren/.test(clean)){const req=state.subtasks.filter(s=>s.status==='Active'&&levelRank[s.requiredLevel]<=levelRank[person.assignedLevel]);const latest=latestResults(person.employeeNumber);const gaps=req.filter(s=>latest.get(person.employeeNumber+'|'+s.id)?.result!=='GO').slice(0,6);answer=es?`${person.name} está en ${a.m.pct}% de preparación. Para avanzar, recomiendo enfocarse primero en: ${gaps.map(x=>x.id+' '+x.name).join('; ')||'mantener sus calificaciones actuales'}.`:`${person.name} is ${a.m.pct}% ready. The best next focus is: ${gaps.map(x=>x.id+' '+x.name).join('; ')||'maintaining current qualifications'}.`}else answer=es?`${person.name}: preparación ${a.m.pct}%, nivel más alto completamente calificado ${a.m.highest}, ${a.m.open} acciones abiertas y ${a.m.critical} fallas críticas. ${a.next}`:`${person.name}: readiness ${a.m.pct}%, highest fully qualified level ${a.m.highest}, ${a.m.open} open actions, and ${a.m.critical} critical failures. ${a.next}`}
if(!answer&&/promotion|promocion|advance|avanz/.test(clean)){rpConversation.lastIntent='promotion';const cand=activePeople().filter(p=>!sh||p.shift===sh).map(p=>({p,...personMetrics(p)})).filter(x=>x.pct>=60&&!x.critical).sort((a,b)=>b.pct-a.pct).slice(0,8);answer=cand.length?(es?'Más cerca de avanzar: ':'Closest to advancement: ')+cand.map(x=>`${x.p.name} (${x.p.shift}, ${x.pct}%, ${x.p.assignedLevel})`).join('; '):(es?'Aún no hay candidatos que cumplan el umbral local de avance.':'No associates currently meet the local advancement threshold.')}
const task=state.tasks.find(x=>clean.includes((x.id||'').toLowerCase())||clean.includes((x.name||'').toLowerCase()));if(!answer&&task){rpConversation.taskId=task.id;rpConversation.lastIntent='task';const subs=state.subtasks.filter(x=>x.taskId===task.id&&x.status==='Active'),critical=subs.filter(x=>x.criticality==='Critical Gate');answer=es?`${task.id} — ${task.name}: ${subs.length} subtareas activas, ${critical.length} Critical Gates y nivel requerido ${task.requiredLevel||'variable'}.`:`${task.id} — ${task.name}: ${subs.length} active subtasks, ${critical.length} Critical Gates, and required level ${task.requiredLevel||'varies'}.`}
if(!answer)answer=es?'No encontré una coincidencia exacta. Prueba: “¿Qué le falta a Luis?”, “Compara turno A con C”, “Muéstrame acciones vencidas” o “¿Quién está listo para promoción?”.':'I could not match that yet. Try: “What does Luis need?”, “Compare A Shift with C Shift”, “Show overdue actions”, or “Who is ready for promotion?”.';rpConversation.lastAnswer=answer;rpConversation.history.push({q:raw,a:answer,time:Date.now()});rpConversation.history=rpConversation.history.slice(-12);return answer}
function engineCenterView(){
  const ruleIssues=RulesEngine.validateState(state);
  const pred=PredictiveEngine.readinessRisk(state,personMetrics).slice(0,6);
  const rec=RPBrainEngine.recommend(state,currentUser,personMetrics);
  const knowledge=KnowledgeEngine.ensure(state);
  const workflows=WorkflowEngine.ensure(state);
  page(uiLanguage==='es'?'Centro de motores RP IA':'RP IA Engine Center',uiLanguage==='es'?'Estado operativo de los siete motores empresariales':'Operational status of the seven enterprise engines',`
  <div class="engine-grid">
    ${[
      ['Eagle AI','Analyzes, converses, and recommends',rec.headline,'brain'],
      ['Workflow Engine','Runs controlled processes and approvals',`${workflows.filter(x=>x.status==='Open').length} open workflows`,'workflow'],
      ['Rules Engine','Applies requirements, authority, and blockers',`${ruleIssues.length} data/rule issue(s)`,'rules'],
      ['Knowledge Engine','Connects approved procedures and training',`${knowledge.filter(x=>x.status==='Approved').length} approved articles`,'knowledge'],
      ['Predictive Engine','Detects readiness trends and risk',pred[0]?`Highest risk: ${esc(pred[0].name)} (${pred[0].risk})`:'Awaiting assessment data','predictive'],
      ['Search Engine','Searches the master record and all linked data','Unified employee-number and name search active','search'],
      ['Audit Engine','Preserves traceability and change history',`${(state.audit||[]).length} audit events`,'audit']
    ].map(x=>`<article class="card engine-card"><span class="engine-status">● Online</span><h3>${x[0]}</h3><p>${x[1]}</p><b>${x[2]}</b></article>`).join('')}
  </div>
  <div class="grid"><div class="card"><h3>Enterprise Search</h3><div class="ask-row"><input id="engineSearch" placeholder="Employee #392, Luis Rosario, M04, screen pack..."><button id="runEngineSearch" class="primary">Search</button></div><div id="engineSearchResults" class="engine-results"></div></div>
  <div class="card"><h3>Knowledge Engine</h3><p>Add approved operating knowledge, procedures, images, and training references.</p><button id="addKnowledge" class="secondary">Add knowledge article</button><div>${knowledge.slice(0,5).map(x=>`<div class="list-link"><span><b>${esc(x.title)}</b><small>${esc(x.category)} · ${esc(x.status)}</small></span></div>`).join('')||'<p>No knowledge articles yet.</p>'}</div></div></div>
  <div class="card"><h3>Rule & data-quality findings</h3>${ruleIssues.slice(0,20).map(x=>`<div class="ai-risk"><b>${esc(x.severity.toUpperCase())}</b><span>${esc(x.message)}</span></div>`).join('')||'<p>No structural issues detected.</p>'}</div>`);
  const run=()=>{const hits=SearchEngine.searchAll(state,$('#engineSearch').value);$('#engineSearchResults').innerHTML=hits.map(x=>`<button class="list-link engineHit" data-type="${x.type}" data-id="${esc(x.id)}"><span><b>${esc(x.title)}</b><small>${esc(x.meta||x.type)}</small></span></button>`).join('')||'<p>No matching records.</p>';$$('.engineHit').forEach(b=>b.onclick=()=>{if(b.dataset.type==='person')personDetail(b.dataset.id);else toast(`${b.dataset.type}: ${b.dataset.id}`)})};
  $('#runEngineSearch').onclick=run;$('#engineSearch').onkeydown=e=>{if(e.key==='Enter')run()};
  $('#addKnowledge').onclick=()=>{const title=prompt('Article title');if(!title)return;const summary=prompt('Approved summary / instructions')||'';const a=KnowledgeEngine.add(state,{title,summary,content:summary,status:'Draft',category:'Procedure'},currentUser);audit('CREATE','Knowledge Article',a.id,`Created ${title}`);engineCenterView()};
}

function metlIntelligence(){const all=aiShiftSummary(''),coverage=aiCoverage(),attention=all.risk.slice(0,5);page('Eagle AI','',`<div class="ai-hero"><div><span class="ai-badge">Powered by RP IA</span><h2>Readiness advisor</h2><p>${uiLanguage==='es'?'Recomendaciones claras basadas en tus datos actuales.':'Clear recommendations based on your current competency data.'}</p></div><div class="ai-score"><b>${all.avg}%</b><span>${uiLanguage==='es'?'preparación del departamento':'department readiness'}</span></div></div><div class="card full brain-ask-first"><h3>Ask Eagle AI</h3><div class="ask-row"><input id="aiQuestion" placeholder="${uiLanguage==='es'?'Ejemplo: ¿Qué necesita John Smith para avanzar?':'Example: What does John Smith need to advance?'}"><button id="askAi" class="primary">${uiLanguage==='es'?'Analizar':'Analyze'}</button></div><div class="quick-prompts"><button>${uiLanguage==='es'?'¿Quién está más cerca de promoción?':'Who is closest to promotion?'}</button><button>${uiLanguage==='es'?'Muestra acciones correctivas vencidas':'Show overdue corrective actions'}</button><button>${uiLanguage==='es'?'Muestra fallas de Critical Gate':'Show critical gate failures'}</button><button>${uiLanguage==='es'?'¿Dónde están los riesgos de cobertura?':'Where are the coverage risks?'}</button></div><div id="aiAnswer" class="ai-answer">${uiLanguage==='es'?'Pregunta en lenguaje natural. Eagle AI recordará el contexto de esta conversación.':'Ask in natural language. Eagle AI will remember the context of this conversation.'}</div></div><div class="grid"><div class="card"><h3>Intelligent priorities</h3>${attention.map(x=>`<button class="list-link aiPerson" data-emp="${x.employeeNumber}"><span><b>${esc(x.name)}</b><small>${x.shift} Shift · ${x.assignedLevel}</small></span><span class="pill ${x.critical?'critical':x.open?'nogo':'warn'}">${x.pct}%</span></button>`).join('')||'<p>No associates require priority attention.</p>'}</div><div class="card"><h3>Coverage risk</h3>${coverage.slice(0,6).map(x=>`<div class="ai-risk"><b>${x.shift} · ${esc(x.sub.id)}</b><span>${esc(x.sub.name)}</span><small>${x.count} independently qualified</small></div>`).join('')||'<p>No low-coverage risks detected.</p>'}</div><div class="card full"><h3>Observation drafting assistant</h3><p>Enter short facts. Eagle AI creates a professional draft for evaluator review.</p><textarea id="aiNotes" rows="3" placeholder="Example: Forgot to verify Keyence laser before startup; coaching provided"></textarea><div class="actions"><select id="aiRating"><option>NO-GO</option><option>REQUIRES ASSISTANCE</option><option>GO</option></select><button id="draftObs" class="secondary">Create draft</button></div><div id="draftAnswer" class="ai-answer muted">No draft created.</div></div></div>`);const run=()=>$('#aiAnswer').textContent=answerMetl($('#aiQuestion').value);$('#askAi').onclick=run;$('#aiQuestion').onkeydown=e=>{if(e.key==='Enter')run()};$$('.quick-prompts button').forEach(b=>b.onclick=()=>{$('#aiQuestion').value=b.textContent;run()});$$('.aiPerson').forEach(b=>b.onclick=()=>{const p=state.personnel.find(x=>x.employeeNumber===b.dataset.emp);$('#aiQuestion').value=p.name;$('#aiAnswer').textContent=answerMetl(p.name)});$('#draftObs').onclick=()=>{const n=$('#aiNotes').value.trim(),r=$('#aiRating').value;if(!n)return toast('Enter the observed facts first');const critical=/laser|lockout|loto|emergency|knife|isobutane|co2|palm|safety/i.test(n);let out=`Assessment result: ${r}. The associate was observed during task performance. ${n.replace(/\.$/,'')}.`;if(r==='NO-GO')out+=` The required performance standard was not fully met. Immediate coaching was documented, and retraining plus direct-observation reassessment are required before independent authorization${critical?' can be restored for this safety-critical activity':''}.`;else if(r==='REQUIRES ASSISTANCE')out+=' The task was completed with assistance and is not approved for independent performance. Additional guided practice and reassessment are recommended.';else out+=' The observed performance met the stated standard; the evaluator must confirm all required evidence and critical gates before approval.';$('#draftAnswer').textContent=out}}

function ensureUserForPerson(p){let u=authUsers.find(x=>String(x.employeeNumber||'')===String(p.employeeNumber)||x.name===p.name);if(!u){u={username:String(p.employeeNumber),name:p.name,employeeNumber:String(p.employeeNumber),role:'viewer',password:'RP'+p.employeeNumber,mustChange:true,maxLevel:p.assignedLevel||'-10',language:'en',manageMetl:false,managePersonnel:false};authUsers.push(u);saveUsers()}return u}
function userEdit(emp){const p=state.personnel.find(x=>x.employeeNumber===emp);if(!p)return;const u=ensureUserForPerson(p),oldP=clone(p),oldU=clone(u);let pendingPhoto=p.photo||'';modal(`<h2>Edit user</h2><div class="user-edit-hero"><div id="userPhotoPreview">${employeePhoto(p,'employee-photo-large')}</div><div><h3>${esc(p.name)}</h3><p>Employee #${esc(p.employeeNumber)} · ${esc(p.shift)} Shift · ${esc(p.role)}</p><label class="photo-upload">Add or change photo<input id="uPhoto" type="file" accept="image/*" capture="environment"></label><button class="secondary" id="uRemovePhoto">Remove photo</button></div></div><div class="form-grid"><label>Employee number<input id="uEmp" value="${esc(p.employeeNumber)}"></label><label>Name<input id="uName" value="${esc(p.name)}"></label><label>Position / role<select id="uRole">${['Operator','Sr. Lead','Supervisor'].map(x=>`<option ${p.role===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Shift<select id="uShift">${['A','B','C','D'].map(x=>`<option ${p.shift===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Assigned qualification<select id="uAssigned">${Object.keys(levelRank).map(x=>`<option ${p.assignedLevel===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Employment status<select id="uStatus">${['Active','Leave of Absence','Inactive','Terminated'].map(x=>`<option ${p.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label>System access<select id="uAccess"><option value="viewer" ${u.role==='viewer'?'selected':''}>Read only</option><option value="evaluator" ${u.role==='evaluator'?'selected':''}>Approved evaluator</option><option value="admin" ${u.role==='admin'?'selected':''}>Administrator</option></select></label><label>Maximum evaluator level<select id="uMax">${Object.keys(levelRank).map(x=>`<option ${u.maxLevel===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Preferred language<select id="uLang"><option value="en" ${u.language!=='es'?'selected':''}>English</option><option value="es" ${u.language==='es'?'selected':''}>Español</option></select></label><label>Account status<select id="uEnabled"><option value="true" ${u.disabled!==true?'selected':''}>Active</option><option value="false" ${u.disabled===true?'selected':''}>Disabled</option></select></label><label class="mini-check"><input id="uManageMetl" type="checkbox" ${u.manageMetl?'checked':''}> Manage METL Tasks and Subtasks</label><label class="mini-check"><input id="uManagePeople" type="checkbox" ${u.managePersonnel?'checked':''}> Manage personnel</label><label class="full">Qualified production lines<input id="uLines" value="${esc(p.qualifiedLines)}"></label><label class="full">Notes<textarea id="uNotes">${esc(p.notes)}</textarea></label></div><div class="actions"><button class="primary" id="saveUserEdit">Save user</button><button class="secondary" id="resetUserPwd">Reset password</button><button class="secondary close">Cancel</button></div>`);$('#uPhoto').onchange=e=>readEmployeePhoto(e.target.files[0],data=>{pendingPhoto=data;$('#userPhotoPreview').innerHTML=data?`<img class="employee-photo-large" src="${data}" alt="Employee photo preview">`:'<div class="employee-photo-large photo-placeholder">?</div>'});$('#uRemovePhoto').onclick=()=>{pendingPhoto='';$('#userPhotoPreview').innerHTML='<div class="employee-photo-large photo-placeholder">?</div>'};$('#resetUserPwd').onclick=()=>{u.password='RP'+p.employeeNumber;u.mustChange=true;saveUsers();audit('RESET','User Password',u.username,'Temporary password restored');toast('Temporary password: RP'+p.employeeNumber)};$('#saveUserEdit').onclick=()=>{const newEmp=$('#uEmp').value.trim(),newName=$('#uName').value.trim();if(!newEmp||!newName)return toast('Employee number and name are required');if(state.personnel.some(x=>x.employeeNumber===newEmp&&x.positionId!==p.positionId))return toast('Employee number must be unique');Object.assign(p,{employeeNumber:newEmp,name:newName,role:$('#uRole').value,shift:$('#uShift').value,assignedLevel:$('#uAssigned').value,status:$('#uStatus').value,qualifiedLines:$('#uLines').value,notes:$('#uNotes').value,photo:pendingPhoto});Object.assign(u,{employeeNumber:newEmp,name:newName,role:$('#uAccess').value,maxLevel:$('#uMax').value,language:$('#uLang').value,disabled:($('#uStatus').value!=='Active'||$('#uEnabled').value!=='true'),manageMetl:$('#uManageMetl').checked,managePersonnel:$('#uManagePeople').checked});if(oldU.username===String(oldP.employeeNumber))u.username=newEmp;saveUsers();audit('UPDATE','Personnel & User',newEmp,'Profile, photo, language, or permissions updated',{person:oldP,user:oldU},{person:p,user:u});closeModal();settings()}}
function settings(){page('Administration','Fast user management, authority, backups, and controlled recovery',`<div class="admin-search card"><div><h3>User management</h3><p>Find an employee, edit authority, or create a new employee and login account.</p><button class="primary" id="adminAddEmployee">Add new employee</button></div><div class="filters"><input id="adminSearch" type="search" placeholder="Search name or employee #"><select id="adminShift"><option value="">All shifts</option>${['A','B','C','D'].map(x=>`<option>${x}</option>`).join('')}</select><select id="adminRole"><option value="">All positions</option><option>Operator</option><option>Sr. Lead</option><option>Supervisor</option></select><select id="adminStatus"><option value="">All employment statuses</option><option>Active</option><option>Leave of Absence</option><option>Inactive</option><option>Terminated</option></select><select id="adminAccess"><option value="">All access levels</option><option value="viewer">Read only</option><option value="evaluator">Evaluator</option><option value="admin">Administrator</option></select></div></div><div id="adminUsers" class="admin-user-grid"></div><div class="grid admin-lower"><div class="card"><h3>System rules</h3><label>Reassessment warning days<input id="setWarn" type="number" value="${state.settings.reassessmentWarningDays}"></label><label>Default corrective-action days<input id="setCA" type="number" value="${state.settings.defaultCorrectiveActionDays}"></label><button class="primary" id="saveSettings">Save settings</button></div><div class="card"><h3>Backup and recovery</h3><button class="secondary" id="backupBtn">Download JSON backup</button><label class="file-label">Restore JSON backup<input id="restoreFile" type="file" accept="application/json"></label><button class="secondary" id="resetBaseline">Restore workbook baseline</button></div><div class="card"><h3>Data exports</h3><button class="secondary" id="exportPeople">Personnel CSV</button><button class="secondary" id="exportTasks">Tasks & subtasks CSV</button><button class="secondary" id="exportAssess2">Assessments CSV</button></div></div>`);const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();const draw=()=>{const q=norm($('#adminSearch').value),sh=$('#adminShift').value,role=$('#adminRole').value,status=$('#adminStatus').value,access=$('#adminAccess').value;const people=state.personnel.filter(p=>p.employeeNumber&&p.name).filter(p=>{const u=authUsers.find(x=>String(x.employeeNumber||'')===String(p.employeeNumber)||x.name===p.name);const hay=norm(`${p.employeeNumber} ${p.name} ${p.role} ${p.shift}`);return(!q||hay.includes(q))&&(!sh||p.shift===sh)&&(!role||p.role===role)&&(!status||p.status===status)&&(!access||(u?.role||'viewer')===access)});$('#adminUsers').innerHTML=people.map(p=>{const u=authUsers.find(x=>String(x.employeeNumber||'')===String(p.employeeNumber)||x.name===p.name)||{role:'viewer',maxLevel:p.assignedLevel};return`<article class="admin-user-card">${employeePhoto(p,'employee-photo')}<div class="admin-user-main"><h3>${esc(p.name)}</h3><p>Employee #${esc(p.employeeNumber)} · ${p.shift} Shift</p><div class="user-meta"><span>${esc(p.role)}</span><span>${esc(p.assignedLevel)}</span><span>${u.role==='evaluator'?'Evaluator '+(u.maxLevel||''):u.role==='admin'?'Administrator':'Read only'}</span></div></div><div class="actions"><button class="primary editUser" data-emp="${p.employeeNumber}">Edit user</button><button class="secondary viewUser" data-emp="${p.employeeNumber}">View profile</button></div></article>`}).join('')||'<div class="card empty-state"><b>No users found</b><p>Try a different name, employee number, shift, or access filter.</p></div>';$$('.editUser').forEach(b=>b.onclick=()=>userEdit(b.dataset.emp));$$('.viewUser').forEach(b=>b.onclick=()=>personDetail(b.dataset.emp))};['adminSearch','adminShift','adminRole','adminStatus','adminAccess'].forEach(id=>['input','change','search'].forEach(ev=>$(`#${id}`).addEventListener(ev,draw)));draw();$('#adminAddEmployee').onclick=()=>personEdit();$('#saveSettings').onclick=()=>{state.settings.reassessmentWarningDays=+$('#setWarn').value;state.settings.defaultCorrectiveActionDays=+$('#setCA').value;audit('UPDATE','System Settings','global','Settings updated');toast('Settings saved')};$('#backupBtn').onclick=()=>download(JSON.stringify(state,null,2),`RP-IA-backup-${today()}.json`,'application/json');$('#restoreFile').onchange=restoreBackup;$('#resetBaseline').onclick=()=>{if(!confirm('Restore workbook baseline? Current pilot changes will be replaced. Download a backup first.'))return;state=normalize(clone(window.METL_BASELINE));audit('RESTORE','System','baseline','Workbook baseline restored');dashboard()};$('#exportPeople').onclick=exportPersonnel;$('#exportTasks').onclick=exportTasks;$('#exportAssess2').onclick=exportAssessments}


function csv(rows){
  return rows.map(row=>row.map(value=>{
    const text=String(value??'');
    return /[",\n\r]/.test(text)?`"${text.replace(/"/g,'""')}"`:text;
  }).join(',')).join('\r\n');
}
function download(content,filename,mime='text/csv;charset=utf-8'){
  const blob=content instanceof Blob?content:new Blob([content],{type:mime});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download=filename;a.style.display='none';
  document.body.appendChild(a);a.click();a.remove();
  setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function exportDashboard(){
  const people=activePeople();
  const metrics=people.map(p=>({...p,...personMetrics(p)}));
  const rows=[
    ['Metric','Value'],
    ['Generated',new Date().toLocaleString()],
    ['Active associates',metrics.length],
    ['Fully ready',metrics.filter(x=>x.pct===100&&!x.open&&!x.critical).length],
    ['Open corrective actions',state.actions.filter(a=>a.status!=='Closed').length],
    ['Critical failures',metrics.reduce((sum,x)=>sum+(x.critical||0),0)],
    ['Overdue actions',state.actions.filter(a=>a.status!=='Closed'&&a.targetDate&&a.targetDate<today()).length],
    [],
    ['Shift','Active associates','Readiness %','Critical failures'],
    ...['A','B','C','D'].map(shift=>{
      const group=metrics.filter(x=>x.shift===shift);
      return [shift,group.length,group.length?Math.round(group.reduce((sum,x)=>sum+x.pct,0)/group.length):0,group.reduce((sum,x)=>sum+(x.critical||0),0)];
    })
  ];
  download(csv(rows),`RP-IA-dashboard-${today()}.csv`);
}

